import {RACES,CLASSES,ORIGINS,OMENS,STAT_LABELS,LORE} from './content.js';
import * as M from './model.js';
import * as S from './saves.js';
import * as AI from './director.js';
import {Realm} from './world.js';

const $=id=>document.getElementById(id),app=$('app'),modalRoot=$('modal-root');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const node=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
const btn=(label,fn,cls='')=>{const b=node('button',cls,label);b.type='button';b.onclick=fn;return b};
let hero=null,realm=null,panel=null,near=null,step=0,draft=null,aiStatus={available:false},aiModel='',saveClock=0,screen='menu',lastFocus=null;
const prefs=(()=>{try{return JSON.parse(localStorage.getItem('sinfall-preferences')||'{}')}catch{return{}}})();
const portrait=(n,cls='')=>{const p=node('div','portrait '+cls);n=M.clamp(Number(n)||0,0,7);p.style.backgroundPosition=`${(n%4)*100/3}% ${Math.floor(n/4)*100}%`;p.setAttribute('role','img');p.setAttribute('aria-label','Adventurer portrait');return p};
const glyph=(s)=>node('span','glyph',s);
function notify(text,type=''){const n=node('div','toast '+type,text);$('notifications').append(n);setTimeout(()=>n.remove(),5200)}
function persist(checkpoint=false){if(!hero)return;const ok=S.saveHero(hero,{checkpoint});if(!ok)notify(S.storageError(),'warning');updateHud();return ok}
function dismiss(){modalRoot.replaceChildren();lastFocus?.focus?.({preventScroll:true});lastFocus=null}
function dialog({tag='',title='',text='',image=null,choices=[],closable=true,wide=false,portraitId=null}){
 lastFocus=document.activeElement;const wrap=node('div','modal-overlay');const d=node('section','dialog '+(wide?'wide-dialog':''));d.setAttribute('role','dialog');d.setAttribute('aria-modal','true');d.setAttribute('aria-label',title);
 if(image){const i=node('img','dialog-art');i.src=image;i.alt='';d.append(i)}
 const body=node('div','dialog-body');if(portraitId!==null)body.append(portrait(portraitId,'speaker-portrait'));if(tag)body.append(node('div','eyebrow',tag));body.append(node('h2','',title));
 const p=node('p','dialog-text',text);body.append(p);const list=node('div','dialog-choices');for(const choice of choices){const[label,fn,detail,disabled]=choice;const b=btn(label,fn);if(detail)b.append(node('small','',detail));b.disabled=!!disabled;list.append(b)}body.append(list);d.append(body);if(closable){const x=btn('×',dismiss,'close-button');x.setAttribute('aria-label','Close dialog');d.append(x)}wrap.append(d);modalRoot.replaceChildren(wrap);d.querySelector('button,input,textarea')?.focus({preventScroll:true});return{wrap,d,body,list,text:p};
}
function confirmAction(title,text,fn){dialog({tag:'A CHOICE TO MAKE',title,text,choices:[['Confirm',()=>{dismiss();fn()}],['Keep things as they are',dismiss]]})}
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=node('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function copyText(text){try{await navigator.clipboard.writeText(text);notify('Copied.')}catch{const d=dialog({tag:'COPY THIS TEXT',title:'Story request',text:'Select and copy the request below.',choices:[['Done',dismiss]]});const t=node('textarea','copy-area');t.value=text;t.readOnly=true;d.body.insertBefore(t,d.list);t.focus();t.select()}}
function disposeWorld(){realm?.dispose();realm=null;near=null;panel=null}

function menu(){
 if(hero)persist();disposeWorld();dismiss();screen='menu';const last=S.lastHero(),heroes=S.listHeroes();
 app.innerHTML='<main class="title-screen"><div class="title-landscape"></div><div class="title-shade"></div><div class="title-top"><span class="seal">✧</span><span>A WORLD THAT REMEMBERS</span></div><section class="title-content"><div class="eyebrow">REALMS OF TEMPTATION</div><h1>SINFALL</h1><p class="title-quote">Every road hides a story.<br>Every choice leaves a scar.</p><nav id="main-menu" aria-label="Main menu"></nav><div id="continue-summary"></div></section><div class="title-footer"><span>THE LIVING REALMS · 1.0</span><button id="how-to">How to play</button><span>Your legends live on this device</span></div></main>';
 const nav=$('main-menu');if(last){nav.append(btn('Continue',()=>load(last.id),'menu-button primary'));$('continue-summary').textContent=`${last.name} · Level ${last.level} ${M.classOf(last).name} · ${last.campaign.title}`}
 nav.append(btn('New Game',creator,'menu-button '+(!last?'primary':'')),btn('Load Game'+(heroes.length?' · '+heroes.length:''),()=>loadScreen(),'menu-button'),btn('Dungeon Master & Settings',()=>settings(),'menu-button subtle'));
 $('how-to').onclick=howTo;
}
function loadScreen(){
 const heroes=S.listHeroes();const d=dialog({tag:'YOUR LEGENDS',title:'Load a hero',text:heroes.length?'Every character keeps a separate life, inventory, and history.':'Your first legend is still unwritten.',choices:[['Create a new character',()=>{dismiss();creator()}],['Import a hero or collection',()=>openImport()],['Back',dismiss]],wide:true});
 const grid=node('div','save-grid');for(const h of heroes){const card=node('article','save-card');card.append(portrait(h.portrait));const content=node('div');content.append(node('h3','',h.name),node('p','',`Level ${h.level} ${M.raceOf(h).name} ${M.classOf(h).name}`),node('small','',h.campaign.title),node('small','',new Date(h.updatedAt).toLocaleString()));const actions=node('div','inline-actions');actions.append(btn('Play',()=>load(h.id),'primary'),btn('Checkpoints',()=>checkpointScreen(h.id)),btn('Export',()=>download('sinfall-'+h.name.replace(/[^a-z0-9]/gi,'-')+'.json',S.exportSave(h))),btn('Delete',()=>confirmAction('Retire '+h.name+'?','This removes this character from this device. Export the hero first if you want to keep them.',()=>{S.deleteHero(h.id);loadScreen()}),'danger-link'));content.append(actions);card.append(content);grid.append(card)}d.body.insertBefore(grid,d.list);
 if(!heroes.length)d.body.insertBefore(node('div','empty-state','Create an adventurer, choose a calling, and walk into the unknown.'),d.list);
}
function checkpointScreen(id){const saves=S.checkpoints(id);dialog({tag:'A MOMENT YOU CAN RETURN TO',title:'Saved checkpoints',text:saves.length?'Restoring keeps the current autosave as another checkpoint.':'Use Save checkpoint from the pause menu to preserve a moment in this hero’s story.',choices:[...saves.map(s=>[new Date(s.at).toLocaleString(),()=>confirmAction('Return to this checkpoint?','Your current progress will be kept as a checkpoint before the earlier moment is restored.',()=>{const current=S.loadHero(id);if(current)S.saveHero(current,{checkpoint:true});hero=structuredClone(s.hero);S.saveHero(hero);dismiss();startGame()}),`${s.hero.name} · Level ${s.hero.level} · ${s.hero.campaign.title}`]),['Back to heroes',loadScreen]]})}
function load(id){const h=S.loadHero(id);if(!h){notify('That save could not be loaded. Your other heroes are safe.');return}hero=h;dismiss();startGame();if(hero.combat)combatDialog()}
function creator(){
 disposeWorld();dismiss();screen='creator';step=0;draft={name:'Raven',raceId:'elf',classId:'ranger',originId:'wanderer',omen:OMENS[Math.floor(Math.random()*OMENS.length)],portrait:1,skin:'#c39c7a',hair:'#ddd7bf',outfit:'#49675c',pronouns:'she/her',backstory:''};renderCreator();
}
function renderCreator(){
 const c=CLASSES.find(c=>c.id===draft.classId),r=RACES.find(r=>r.id===draft.raceId);
 app.innerHTML='<main class="creator-screen"><div class="creator-top"><button id="creator-exit" class="text-button">← Main menu</button><span class="wordmark">SINFALL</span><span>CREATE YOUR LEGEND</span></div><div class="creator-layout"><aside id="hero-preview"><div class="preview-frame" id="preview-art"></div><div class="preview-caption"><div class="eyebrow">THE ONE WHO CHOOSES</div><h2 id="preview-name"></h2><p id="preview-class"></p><div id="preview-stats" class="stat-line"></div></div></aside><section class="creator-sheet"><div class="creation-steps" id="creation-steps"></div><div id="creation-content"></div><div class="creator-actions"><button id="creator-back" class="text-button">← Back</button><button id="creator-next" class="primary">Continue →</button></div></section></div></main>';
 $('creator-exit').onclick=()=>menu();$('preview-art').append(portrait(draft.portrait,'large-portrait'));$('preview-name').textContent=draft.name||'Your name';$('preview-class').textContent=r.name+' · '+c.name;$('preview-stats').textContent=Object.entries(c.stats).map(([k,v])=>STAT_LABELS[k]+' +'+(v+(r.stats[k]||0)+(ORIGINS.find(o=>o.id===draft.originId)?.stat===k?1:0))).join('  ·  ');
 ['Identity','Calling','History','Appearance'].forEach((v,i)=>{const s=node('span',i===step?'active':i<step?'done':'',`${i<step?'✓':i+1} ${v}`);$('creation-steps').append(s)});
 const body=$('creation-content');
 if(step===0){body.append(node('div','eyebrow','01 / AN UNWRITTEN NAME'),node('h2','', 'Who walks this road?'),node('p','muted','Your ancestry shapes your gifts. Your decisions shape everything else.'));
  const l=node('label','field-label','Your name'),input=node('input');input.id='hero-name';input.value=draft.name;input.maxLength=32;input.autocomplete='off';input.oninput=()=>{draft.name=input.value;$('preview-name').textContent=input.value||'Your name'};l.append(input);body.append(l);
  const grid=node('div','ancestry-grid');for(const race of RACES){const b=btn(race.name,()=>{draft.raceId=race.id;renderCreator()},'choice-card '+(race.id===draft.raceId?'selected':''));b.append(node('span','',race.desc),node('small','',race.trait));grid.append(b)}body.append(grid);
 }
 if(step===1){body.append(node('div','eyebrow','02 / A WAY THROUGH THE WORLD'),node('h2','','Choose your calling'),node('p','muted','Every calling has a distinct combat ability and a branching talent tree.'));
  const grid=node('div','class-grid');for(const cls of CLASSES){const b=btn(cls.name,()=>{draft.classId=cls.id;draft.outfit=cls.color;renderCreator()},'choice-card '+(cls.id===draft.classId?'selected':''));b.append(node('small','',cls.role));grid.append(b)}body.append(grid);const info=node('div','class-detail');info.append(node('h3','',c.name),node('p','',c.desc),node('strong','',c.ability.name+' · '+c.ability.cost+' mana'),node('p','muted',c.ability.desc),node('small','',`${c.hp} base vitality · ${c.mp} base mana · ${c.weapon}`));body.append(info);
 }
 if(step===2){body.append(node('div','eyebrow','03 / WHAT CAME BEFORE'),node('h2','','Everyone carries a past'));
  const grid=node('div','origin-grid');for(const o of ORIGINS){const b=btn(o.name,()=>{draft.originId=o.id;renderCreator()},'choice-card '+(o.id===draft.originId?'selected':''));b.append(node('span','',o.text),node('small','',`+1 ${STAT_LABELS[o.stat]}`));grid.append(b)}body.append(grid);
  const label=node('label','field-label','Your omen'),s=node('select');for(const omen of OMENS){const option=node('option','',omen);option.value=omen;s.append(option)}s.value=draft.omen;s.onchange=()=>draft.omen=s.value;label.append(s);body.append(label);
  const l=node('label','field-label','A personal history · optional'),t=node('textarea');t.maxLength=600;t.rows=3;t.placeholder='A promise, a person, something you hope to find…';t.value=draft.backstory;t.oninput=()=>draft.backstory=t.value;l.append(t);body.append(l);
 }
 if(step===3){body.append(node('div','eyebrow','04 / A FACE FOR THE LEGEND'),node('h2','','Make this hero yours'),node('p','muted','Choose a painted portrait. Your colors also appear on your character in the world.'));
  const grid=node('div','portrait-picker');for(let i=0;i<8;i++){const b=btn('',()=>{draft.portrait=i;draft.pronouns=i<4?'she/her':'he/him';renderCreator()},draft.portrait===i?'selected':'');b.setAttribute('aria-label','Choose portrait '+(i+1));b.append(portrait(i));grid.append(b)}body.append(grid);
  const colors=node('div','appearance-controls');for(const[key,title,values]of[['outfit','Cloak',['#49675c','#476b86','#7e4d50','#9b8456','#4a4358','#8d6e57']],['hair','Hair',['#382b24','#ddd7bf','#9e5d39','#212629','#9a7c4b']],['skin','Skin',['#e5c3a2','#c39c7a','#9c7151','#644736']]]){const row=node('div','color-row');row.append(node('span','',title));for(const v of values){const b=btn('',()=>{draft[key]=v;renderCreator()},'swatch '+(draft[key]===v?'selected':''));b.style.backgroundColor=v;b.setAttribute('aria-label',title+' '+v);row.append(b)}colors.append(row)}body.append(colors);
  const l=node('label','field-label','Pronouns'),s=node('select');for(const p of['she/her','he/him','they/them']){const o=node('option','',p);s.append(o)}s.value=draft.pronouns;s.onchange=()=>draft.pronouns=s.value;l.append(s);body.append(l);
  if(aiStatus.sharing){const l=node('label','checkbox-label'),i=node('input');i.type='checkbox';i.checked=draft.useAI!==false;i.onchange=()=>draft.useAI=i.checked;l.append(i,node('span','','Let ChatGPT write this campaign · uses your plan'));body.append(l)}
 }
 $('creator-back').disabled=step===0;$('creator-back').onclick=()=>{step--;renderCreator()};$('creator-next').textContent=step===3?'Begin your story ✦':'Continue →';$('creator-next').onclick=()=>{if(!draft.name.trim()){notify('Give your hero a name.');$('hero-name')?.focus();return}if(step<3){step++;renderCreator();window.scrollTo(0,0)}else{hero=M.makeHero(draft);persist(true);startGame();if(aiStatus.sharing&&draft.useAI!==false)generateAdventure(true);else introduction()}};
}
function introduction(){dialog({tag:`CHAPTER I · ${hero.world.towns[0].name.toUpperCase()}`,title:hero.campaign.title,text:`You come to ${hero.world.towns[0].name} with a past you have not escaped. ${hero.omen}\n\n${hero.campaign.witness}\n\n${M.objective(hero)}`,image:'assets/cover.webp',choices:[['Enter the village',dismiss,'Walk, listen, and decide what kind of person you will be.']]})}
function startGame(){
 disposeWorld();dismiss();screen='world';saveClock=0;
 app.innerHTML='<main class="game-screen"><canvas id="realm" aria-label="Walkable game world"></canvas><div id="world-fallback" hidden><div></div><p>Your browser could not start the 3D view. Nearby places remain playable below.</p><div id="fallback-actions"></div></div><div class="vignette"></div><header class="game-top"><button id="pause" class="crest-button" aria-label="Pause menu">✧</button><div class="hero-hud"><div id="hud-portrait"></div><div><strong id="hud-name"></strong><div class="resource-bar vitality"><span id="hp-fill"></span><small id="hp-label"></small></div><div class="resource-bar mana"><span id="mp-fill"></span><small id="mp-label"></small></div></div></div><div class="compass"><span>N</span><i></i><strong id="compass-heading">N</strong><i></i><span>S</span></div><button id="quick-save" class="save-indicator">◇ Saved</button></header><section class="quest-hud"><div class="eyebrow" id="hud-campaign"></div><p id="hud-objective"></p><button id="quest-details" class="text-button">Open journal →</button></section><aside class="map-hud"><button id="minimap-button" aria-label="Open world map"><canvas id="minimap" width="136" height="136"></canvas></button><div id="hud-location"></div><small id="hud-day"></small></aside><div class="world-caption"><span id="world-location-name"></span><span id="world-location-desc"></span></div><div id="interaction-prompt" hidden><div><span id="near-role"></span><strong id="near-name"></strong></div><button id="interact" class="primary"><kbd>E</kbd> Interact</button></div><div class="movement-hint">W A S D <span>walk</span> · drag <span>look</span> · E <span>interact</span> · Shift <span>run</span></div><div id="joystick" aria-label="Movement joystick" role="application"><span></span></div><button id="touch-run" aria-label="Toggle run" class="touch-run">⇧</button><nav class="game-nav" aria-label="Game panels"><button data-panel="character"><span>♙</span>Character</button><button data-panel="inventory"><span>♧</span>Satchel</button><button data-panel="journal"><span>▤</span>Journal</button><button data-panel="map"><span>⌖</span>Map</button><button data-panel="director"><span>✧</span>Dungeon Master</button><button id="nearby"><span>◎</span>Nearby</button></nav><div id="side-panel"></div><div id="save-warning" hidden></div></main>';
 $('hud-portrait').append(portrait(hero.portrait));$('pause').onclick=pauseMenu;$('quick-save').onclick=()=>{persist(true);notify('Checkpoint saved.');};$('quest-details').onclick=()=>openPanel('journal');$('minimap-button').onclick=()=>openPanel('map');for(const b of document.querySelectorAll('[data-panel]'))b.onclick=()=>openPanel(b.dataset.panel);$('nearby').onclick=nearbyMenu;$('interact').onclick=()=>interact(near);$('touch-run').onclick=()=>{if(realm){if(realm.keys.has('shift'))realm.keys.delete('shift');else realm.keys.add('shift');$('touch-run').classList.toggle('active',realm.keys.has('shift'))}};
 updateHud();
 try{realm=new Realm($('realm'),{hero,onNear:e=>{near=e;updateNear()},onInteract:interact,onRumor:overhear,onTick:dt=>{saveClock+=dt;if(saveClock>15){saveClock=0;persist()}},paused:()=>!!modalRoot.children.length||!!panel||!!hero.combat,quality:prefs.quality||'high'})}
 catch(err){console.warn('3D view unavailable:',err.message);$('realm').hidden=true;$('world-fallback').hidden=false;fallbackActions()}
 if(hero.combat)combatDialog();
}
function updateNear(){$('interaction-prompt')?.toggleAttribute('hidden',!near);if(near){$('near-name').textContent=near.name;$('near-role').textContent=near.role?near.role.toUpperCase():near.type==='enemy'||near.type==='boss'?'DANGER':near.marker?'QUEST':'DISCOVER';$('interact').innerHTML=near.type==='npc'?'<kbd>E</kbd> Talk':'<kbd>E</kbd> Interact'}}
function updateHud(){if(screen!=='world'||!hero||!$('hud-name'))return;const h=hero;$('hud-name').textContent=h.name+' · '+h.level;$('hp-label').textContent=Math.ceil(h.hp)+' / '+M.maxHp(h);$('mp-label').textContent=Math.ceil(h.mp)+' / '+M.maxMp(h);$('hp-fill').style.width=h.hp/M.maxHp(h)*100+'%';$('mp-fill').style.width=h.mp/M.maxMp(h)*100+'%';$('hud-campaign').textContent=h.campaign.title;$('hud-objective').textContent=M.objective(h);$('hud-location').textContent=M.locationName(h);$('hud-day').textContent=`Day ${h.world.day} · ${String(Math.floor(h.world.hour)).padStart(2,'0')}:00`;$('world-location-name').textContent=M.locationName(h);$('world-location-desc').textContent=h.location.type==='town'?M.townOf(h).description:h.location.type==='wilds'?'The old road remembers every traveler.':'Some doors were sealed for a reason.';const err=S.storageError();$('save-warning').hidden=!err;if(err)$('save-warning').textContent=err;realm?.refresh();if(!realm)fallbackActions()}
function fallbackActions(){if(!$('fallback-actions')||!hero)return;const a=$('fallback-actions');a.replaceChildren();for(const e of M.entitiesFor(hero))a.append(btn(e.name,()=>interact(e)))}
function changeLocation(type,townId=hero.location.townId){dismiss();panel=null;$('side-panel')?.replaceChildren();M.changeLocation(hero,type,townId);near=null;updateNear();persist();notify(M.locationName(hero),'location')}
function nearbyMenu(){const a=M.entitiesFor(hero).map(e=>({e,d:Math.hypot(e.x-hero.position.x,e.z-hero.position.z)})).filter(v=>!realm||v.d<9).sort((a,b)=>a.d-b.d);dialog({tag:'LOOK AROUND',title:'Nearby',text:a.length?'Use the world to approach a person or place. Close encounters can be selected here.':'Nothing is close by. Follow the road, or consult your map.',choices:[...a.map(({e,d})=>[e.name,()=>{if(!realm||d<3.4){dismiss();interact(e)}else{dismiss();notify('Head toward '+e.name+' · '+Math.ceil(d)+' meters away.')}},d<3.4?'Within reach':Math.ceil(d)+' m']),['Keep walking',dismiss]]})}
function pauseMenu(){persist();dialog({tag:'A MOMENT BETWEEN STORIES',title:hero.name,text:`Level ${hero.level} ${M.classOf(hero).name} · ${hero.gold} gold\n${hero.campaign.title}`,choices:[['Return to the world',dismiss],['Save checkpoint',()=>{persist(true);dismiss();notify('Checkpoint saved.')}],['Load a hero',loadScreen],['Dungeon Master & settings',settings],['Export this hero',()=>download('sinfall-hero.json',S.exportSave(hero))],['Main menu',menu]]})}
function overhear(){if(hero.location.type!=='town')return;const key='gossip-'+hero.location.townId;if(hero.world.rumors.includes(key))return;hero.world.rumors.push(key);const q=M.discoverRumor(hero,'innkeeper');notify('Overheard: “Something’s been moving in the old crypt. Ask the innkeeper.”','rumor');persist()}

function interact(e){
 if(!e||hero.combat)return;if(modalRoot.children.length)return;panel=null;$('side-panel').replaceChildren();
 if(e.type==='npc'){talk(e);return}
 if(e.type==='travel'){travelMenu();return}
 if(e.type==='exit'){changeLocation(hero.location.type==='dungeon'?'wilds':'town');return}
 if(e.type==='gate'){
  if(hero.location.townId===0&&['arrival','trail','counsel'].includes(hero.campaign.stage)){dialog({tag:'A SEALED THRESHOLD',title:'The undercrypt',text:'A ward denies your passage. The scholar at the Lantern Archive may know why. Follow the mystery in the village first.',choices:[['Return to the road',dismiss]]});return}
  dialog({tag:'BELOW THE ROOTS',title:'Enter the undercrypt?',text:'A narrow stair descends into the earth. Take healing draughts, read your enemies’ intentions, and remember the way back.',choices:[['Descend',()=>changeLocation('dungeon')],['Not yet',dismiss]]});return;
 }
 if(e.type==='enemy'||e.type==='boss'){
  dialog({tag:e.type==='boss'?'THE GUARDIAN':'A HOSTILE PRESENCE',title:e.name,text:e.type==='boss'?'The chamber grows quiet. A figure waits between you and the heart of the mystery.':'The creature watches you. You have a moment to prepare, or withdraw.',choices:[['Engage',()=>{dismiss();M.startCombat(hero,e);persist();combatDialog()}],['Withdraw',dismiss]]});return;
 }
 if(e.type==='clue'){
  const can=hero.location.townId===0&&hero.campaign.stage==='trail';dialog({tag:'A THREAD TO FOLLOW',title:'Strange remains',text:can?hero.campaign.clue:'Old stones hum softly. Whatever happened here left a mark that rain cannot wash away.',choices:[can?['Collect the evidence',()=>{M.collectClue(hero);persist();dismiss();notify('Evidence collected. Speak with the scholar.','quest')}]:['Examine the stones',()=>{if(!M.isResolved(hero,'clue-lore')){M.resolveEntity(hero,'clue-lore');M.gainXp(hero,12);persist()}dismiss()}],['Leave',dismiss]]});return;
 }
 if(e.type==='artifact'){if(hero.campaign.stage==='heart')artifactDialog();else dialog({tag:'AN ECHO REMAINS',title:hero.campaign.artifact,text:'The place remembers your choice. There is nothing more to take.',choices:[['Leave it in peace',dismiss]]});return}
 if(e.type==='chest'){dialog({tag:'WHAT REMAINS',title:e.name,text:'An old iron lock protects something that might be worth the risk.',choices:[['Pick the lock · Finesse',()=>resolveLoot(e,'finesse')],['Force it · Might',()=>resolveLoot(e,'might')],['Unweave the ward · Lore',()=>resolveLoot(e,'lore')],['Leave it',dismiss]]});return}
 if(e.type==='shrine'||e.type==='herbs'){const result=M.interactionReward(hero,e);persist();dialog({tag:e.type==='shrine'?'A SMALL MERCY':'THE GIFTS OF THE ROAD',title:e.name,text:result.text||'You have already tended this place.',choices:[['Continue',dismiss]]});return}
 if(e.type==='traveler'){courier(e);return}
 if(e.type==='board'){noticeBoard();return}
 if(e.type==='lore'){M.resolveEntity(hero,e.id);M.gainXp(hero,15);persist();dialog({tag:'WORDS THAT OUTLASTED THEIR WRITER',title:'An old inscription',text:LORE[(hero.world.seed+hero.world.day)%LORE.length],choices:[['Remember it',dismiss]]})}
}
function resolveLoot(e,stat){const result=M.interactionReward(hero,e,stat);persist();dialog({tag:'THE DICE HAVE SPOKEN',title:e.name,text:result.text,choices:[['Continue',dismiss]]})}
function npcGreeting(e){const c=hero.campaign,town=M.townOf(hero),rel=hero.relationships[e.name]||0;if(rel>=15)return`“${hero.name}. A welcome sight. You kept your word when it mattered.”`;const by={innkeeper:'“A room, a drink, or a story? I can promise the first two are safe.”',smith:'“Steel has honest problems. People don’t. What can I do for you?”',scholar:'“Before you say anything: have you noticed whether your shadow arrived at the same time as you?”',healer:'“You look like someone who finds trouble more easily than sleep. Come closer.”',warden:c.flags.alliance==='veil'?'“The watch has heard who you’ve been speaking to. Tread carefully.”':'“Keep the peace, pay your debts, and leave the chapel bells alone.”',witness:hero.location.townId===0?c.witness:'“Strange travelers have passed this way. I don’t suppose you’re an ordinary one?”',stranger:c.flags.alliance==='wardens'?'“I hear you trust uniforms. How convenient for them.”':'“There are bargains the market cannot offer. I suspect you already know that.”'};return by[e.role]||'“The road has brought us another stranger.”'}
function talk(e){
 const choices=[];if(e.role==='witness'&&hero.location.townId===0&&hero.campaign.stage==='arrival')choices.push(['Tell me everything',()=>dialog({tag:'THE FIRST THREAD',title:hero.campaign.title,text:`${hero.campaign.witness}\n\n“Search the strange remains on the road. Then take what you find to ${hero.world.towns[0].npcs.scholar.name} at the archive. Please. Someone has to remember.”`,choices:[['I’ll look into it',()=>{M.acceptMain(hero);hero.relationships[e.name]=5;persist();dismiss();notify('Main quest added to the journal.','quest')}],['I need to think',()=>talk(e)]]})]);
 if(e.role==='scholar'&&hero.location.townId===0&&hero.campaign.stage==='counsel')choices.push(['Show the evidence',allianceDialog,'Decide whom to trust with what you have learned.']);
 for(const q of hero.world.quests.filter(q=>q.giver===e.name&&q.state==='ready'))choices.push(['Turn in: '+q.title,()=>{M.turnIn(hero,q.id);persist();talk(e);notify('Quest complete · rewards added.','quest')}]);
 choices.push(['What have you heard?',()=>rumorDialog(e),'Rumors can reveal side quests.']);
 if(e.role==='innkeeper')choices.push([`A room · ${8+Math.floor(hero.level/3)} gold`,()=>{if(!M.rest(hero)){notify('You need more gold for a room.');return}persist();dismiss();notify('Rested. A new day begins.')}]);
 if(['smith','healer','stranger'].includes(e.role))choices.push([e.role==='smith'?'Show me your wares':e.role==='healer'?'I need supplies':'What are you offering?',()=>shop(e)]);
 choices.push(['Ask something of your own',()=>directorConversation(e),'An open conversation with the AI dungeon master.'],['Until next time',dismiss]);
 dialog({tag:e.role.toUpperCase()+' · '+e.building,title:e.name,text:npcGreeting(e),portraitId:e.portrait,choices});
}
function rumorDialog(e){const q=M.discoverRumor(hero,e.role);persist();if(q.state==='complete'){dialog({tag:'A DEBT REMEMBERED',title:e.name,text:'“You already helped with that business. People still speak of it. There is always another road, though.”',choices:[['Back',()=>talk(e)]]});return}dialog({tag:'A STORY AT THE EDGE OF THE MAIN ONE',title:q.title,text:`${q.giver}: “${q.description}”\n\nReward: ${q.reward} gold, 50 XP, a healing draught, and their gratitude.\n${q.state==='active'?`Progress: ${q.progress} / ${q.goal}`:''}`,choices:[q.state==='offered'?['I’ll help',()=>{M.acceptSide(hero,q.id);persist();dismiss();notify('Side quest accepted.','quest')}]:q.state==='ready'?['Finish the task',()=>{M.turnIn(hero,q.id);persist();dismiss()}]:['I’m still working on it',dismiss],['Back',()=>talk(e)]]})}
function allianceDialog(){dialog({tag:'TRUST HAS A PRICE',title:'Whose truth?',text:`${hero.campaign.clue}\n\nThe archive has traced the anomaly to the sealed undercrypt. Three people offer a way in. Each asks you to trust a different kind of power.`,choices:[['Tell the wardens',()=>chooseAlliance('wardens'),'Gain strong armor and the watch’s support. The Veil’s agents will distrust you.'],['Work with the scholars',()=>chooseAlliance('scholars'),'A counter-ritual weakens the guardian. The watch is left in the dark.'],['Accept the stranger’s pact · 25 gold',()=>chooseAlliance('veil'),'Gain 5 permanent vitality. Something beyond the Veil learns your name.',hero.gold<25],['I’m not ready',dismiss]]})}
function chooseAlliance(choice){if(!M.chooseAlliance(hero,choice))return;persist();dismiss();notify('The undercrypt is open. Your alliance will be remembered.','quest')}
function shop(e){
 const options=[];if(e.role!=='stranger'||hero.campaign.flags.alliance!=='wardens'){
 options.push(['Healing draught · 12 gold',()=>buy('potion',12,e),'Restores 22+ vitality.'],['Moonwater · 10 gold',()=>buy('mana',10,e),'Restores 16 mana.']);
 if(e.role!=='healer'){const price=40+hero.level*8;options.push([`Commission equipment · ${price} gold`,()=>{if(hero.gold<price){notify('Not enough gold.');return}hero.gold-=price;const item=M.loot(hero);persist();notify('Received '+item.name);shop(e)},'A newly forged weapon, armor, or trinket.']);const cost=25+hero.equipment.weapon.power*5;options.push([`Improve your weapon · ${cost} gold`,()=>{if(hero.gold<cost){notify('Not enough gold.');return}hero.gold-=cost;hero.equipment.weapon.power+=2;M.addLog(hero,'Your weapon was improved by 2 power.','gear');persist();shop(e)},'+2 permanent weapon power.']);const gear=hero.items.filter(i=>['weapon','armor','trinket'].includes(i.type));if(gear.length)options.push(['Sell carried equipment',()=>sellDialog(e)])}}
 dialog({tag:'THE MARKET · '+hero.gold+' GOLD',title:e.name,text:e.role==='stranger'&&hero.campaign.flags.alliance==='wardens'?'“You chose your friends. Ask them for supplies.”':'“Take what you need. The road does not offer refunds.”',choices:[...options,['Back',()=>talk(e)]]});
}
function buy(type,price,e){if(hero.gold<price){notify('Not enough gold.');return}hero.gold-=price;hero.items.push({id:M.uid(),type,name:type==='potion'?'Healing Draught':'Moonwater',qty:1});persist();shop(e)}
function sellDialog(e){dialog({tag:'SELL EQUIPMENT',title:'What can you spare?',text:'Your currently equipped items stay with you.',choices:[...hero.items.filter(i=>['weapon','armor','trinket'].includes(i.type)).map(item=>[item.name+' · '+Math.max(6,item.power*3)+' gold',()=>{hero.items=hero.items.filter(i=>i.id!==item.id);hero.gold+=Math.max(6,item.power*3);persist();sellDialog(e)}]),['Back',()=>shop(e)]]})}
function noticeBoard(){const d=dialog({tag:'THE VILLAGE NOTICE BOARD',title:'Work for the willing',text:'Handwritten notices overlap old proclamations. Their authors are somewhere in this village.',choices:[['Walk away',dismiss]]});for(const role of['innkeeper','healer','smith']){const q=M.discoverRumor(hero,role),card=node('div','notice');card.append(node('h3','',q.title),node('p','',q.description),node('small','',q.giver+' · '+q.reward+' gold'));if(q.state==='offered')card.append(btn('Accept',()=>{M.acceptSide(hero,q.id);persist();dismiss();notify('Quest accepted.','quest')},'primary'));else card.append(node('small','',q.state));d.body.insertBefore(card,d.list)}persist()}
function courier(e){
 const q=M.discoverRumor(hero,'stranger');if(q.state==='offered')M.acceptSide(hero,q.id);dialog({tag:'A STRANGER ON THE ROAD',title:'A letter without a name',text:'The courier’s satchel is torn. A sealed letter lies in the mud. “It isn’t for anyone living,” they say. “That doesn’t mean it should be opened.”',choices:[['Return it sealed',()=>{M.resolveEntity(hero,e.id);M.progressSide(hero,'courier');hero.factions.town++;M.addLog(hero,'You returned the dead letter unopened. Someone’s last secret stays theirs.');persist();dismiss();notify('Return to the stranger in town.','quest')}],['Read it first · Lore check',()=>{const c=M.check(hero,'lore',12);M.resolveEntity(hero,e.id);M.progressSide(hero,'courier');M.gainXp(hero,c.success?30:10);hero.factions.veil++;M.addLog(hero,c.success?'The letter describes tomorrow’s weather and the precise moment you will hear a bell.':'The writing rearranges itself. You close it before it can finish spelling your name.');persist();dismiss();notify('The letter’s secret joins your journal.','quest')}],['Leave the courier alone',dismiss]]});persist();
}
function artifactDialog(){const c=hero.campaign;dialog({tag:'WHAT WILL YOU LEAVE BEHIND?',title:c.artifact,text:c.revelation+'\n\n'+c.demand,image:'assets/veil.webp',choices:[['Preserve it · find another way',()=>ending('preserve'),'Support the scholars; receive protective legacy equipment.'],['Destroy it · end the bargain',()=>ending('destroy'),'Earn the town’s trust; receive a legacy weapon.'],['Bind it to yourself · bear the cost',()=>ending('bind'),'Deepen your bond with the Veil; receive a powerful trinket.'],['Leave the decision for later',dismiss]]})}
function ending(choice){const item=M.finishCampaign(hero,choice);if(!item)return;persist(true);dialog({tag:'AN ENDING · NOT THE END',title:hero.campaign.title,text:hero.campaign[choice]+`\n\n${hero.name} has changed this place. +1 talent point, experience, gold, and ${item.name}. Your character’s journey continues.`,image:'assets/veil.webp',choices:[['Stay in this world',()=>{changeLocation('town',0);notify('Your decision lives in your chronicle.')}],['A new adventure · keep this hero',newAdventure,'Keep your levels, talents, equipment, relationships, and past decisions.']]})}
function newAdventure(){confirmAction('Take the next road?','This closes the current world. Your hero, equipment, talents, and chronicle endure. Export a checkpoint if you want to revisit this realm.',()=>{M.newCampaign(hero);persist(true);startGame();if(aiStatus.sharing)generateAdventure(true);else introduction()})}

function combatDialog(){
 const c=hero.combat;if(!c)return;const intent=M.combatIntent(hero),intentText={quick:'A quick strike · steady damage',heavy:'A heavy blow · guard to absorb it',hex:'A gathering hex · interrupt or brace',guard:'A defensive stance · recover or prepare'}[intent],ab=M.classOf(hero).ability;
 const d=dialog({tag:c.boss?'THE GUARDIAN · ROUND '+(c.round+1):'COMBAT · ROUND '+(c.round+1),title:c.name,text:c.log[0],closable:false,choices:[['Strike',()=>fight('attack'),'Weapon damage · no mana cost'],[ab.name+' · '+M.abilityCost(hero)+' mana',()=>fight('ability'),ab.desc,hero.mp<M.abilityCost(hero)],['Guard & focus',()=>fight('guard'),'Absorb 7+ damage this round; recover 4 mana.'],['Drink healing draught',()=>fight('potion'),'Restore vitality; the enemy still acts.',!hero.items.some(i=>i.type==='potion'&&i.qty>0)||hero.hp>=M.maxHp(hero)],['Attempt escape',()=>fight('flee'),'Finesse check. Failure lets the foe act.']]});
 const bars=node('div','combat-status');bars.innerHTML=`<div class="enemy-portrait ${esc(c.boss?'knight':c.kind)}" role="img" aria-label="${esc(c.name)}"></div><div class="enemy-health"><span style="width:${Math.max(0,c.hp/c.maxHp*100)}%"></span></div><div class="combat-numbers"><span>${Math.ceil(c.hp)} / ${c.maxHp} enemy vitality</span><span>♥ ${hero.hp} · ✧ ${hero.mp}</span></div><p class="enemy-intent">${esc(intentText)}</p>`;d.body.insertBefore(bars,d.text);d.list.classList.add('combat-choices');
 if(c.log.length>1){const log=node('details','combat-log');log.append(node('summary','','Previous rounds'));for(const text of c.log.slice(1))log.append(node('p','',text));d.body.append(log)}
}
function fight(action){const result=M.combatTurn(hero,action);if(!result.ok){notify(result.reason||'That action is unavailable.');return}persist();if(result.outcome==='round'){combatDialog();return}if(result.outcome==='victory'){dialog({tag:'VICTORY',title:result.boss?'The guardian falls':'The road is yours',text:result.text+`\n\n+${result.xp} XP · +${result.gold} gold${result.item?'\n'+result.item.name:''}`+(result.boss&&hero.location.townId===0?'\n\n'+hero.campaign.revelation:''),choices:[['Continue',()=>{dismiss();updateHud();if(result.boss&&hero.location.townId===0)notify('The artifact waits in the chamber.','quest')}]]});return}if(result.outcome==='defeat'){dialog({tag:'STILL BREATHING',title:'The infirmary',text:hero.history[0].text,choices:[['Get back on your feet',()=>{dismiss();updateHud()}]]});return}dismiss();notify('You slip away. The creature remains.')}

function openPanel(name){
 if(hero.combat)return;if(panel===name){panel=null;$('side-panel').replaceChildren();return}panel=name;const p=$('side-panel');p.innerHTML=`<aside class="side-panel" role="dialog" aria-modal="false" aria-label="${esc(name)}"><header><span class="eyebrow">${esc(name==='director'?'DUNGEON MASTER':name)}</span><button id="close-panel" aria-label="Close panel">×</button></header><div id="panel-body"></div></aside>`;$('close-panel').onclick=()=>{panel=null;p.replaceChildren()};const b=$('panel-body');
 if(name==='character')characterPanel(b);if(name==='inventory')inventoryPanel(b);if(name==='journal')journalPanel(b);if(name==='map')mapPanel(b);if(name==='director')directorPanel(b);document.querySelectorAll('[data-panel]').forEach(v=>v.classList.toggle('selected',v.dataset.panel===name));
}
function characterPanel(b){b.append(portrait(hero.portrait,'character-portrait'),node('h2','',hero.name),node('p','muted',`${M.raceOf(hero).name} ${M.classOf(hero).name} · Level ${hero.level}`),node('p','',ORIGINS.find(o=>o.id===hero.originId)?.name),node('p','muted',hero.omen));if(hero.backstory)b.append(node('p','',hero.backstory));const grid=node('div','stats-grid');for(const[k,v]of Object.entries(M.stats(hero))){const s=node('div');s.append(node('strong','',v),node('span','',STAT_LABELS[k]));grid.append(s)}b.append(grid,node('p','xp-label',`${hero.xp} / ${M.xpNeeded(hero)} XP · ${hero.talentPoints} talent points`),node('h3','','Ascension'));
 for(const t of M.classOf(hero).talents){const owned=hero.talents.includes(t.id),locked=t.requires&&!hero.talents.includes(t.requires),card=node('div','talent '+(owned?'learned':locked?'locked':''));card.append(node('h4','',t.name),node('p','',t.desc));const button=btn(owned?'✓ Learned':locked?'Requires '+M.classOf(hero).talents.find(v=>v.id===t.requires).name:'Learn · 1 point',()=>{if(M.unlock(hero,t.id)){persist();panel=null;openPanel('character');notify('Learned '+t.name,'level')}},owned?'text-button':'');button.disabled=owned||!!locked||hero.talentPoints<1;card.append(button);b.append(card)}
 b.append(node('h3','','Reputation'));for(const[k,v]of Object.entries(hero.factions))b.append(node('p','',`${k==='town'?'Townsfolk':k==='scholars'?'Scholars':'The Veil'} · ${v}`));
}
function inventoryPanel(b){b.append(node('h2','','Armory & satchel'),node('p','gold-label',hero.gold+' gold'),node('h3','','Equipped'));for(const[slot,item]of Object.entries(hero.equipment)){const card=node('div','item-card equipped');card.append(glyph(slot==='weapon'?'⚔':slot==='armor'?'♜':'◈'),node('div','',item.name),node('small','',`${slot} · ${item.power} power`));b.append(card)}b.append(node('h3','','Carried'));if(!hero.items.length)b.append(node('p','muted','Your satchel is empty.'));
 hero.items.forEach(item=>{const card=node('div','item-card');const text=node('div');text.append(node('strong','',item.name),node('small','',item.qty?'×'+item.qty:item.power?item.power+' power':item.type));card.append(text);if(['weapon','armor','trinket'].includes(item.type))card.append(btn('Equip',()=>{M.equip(hero,item.id);persist();panel=null;openPanel('inventory')}));if(['potion','mana'].includes(item.type)){const use=btn('Use',()=>{if(M.useItem(hero,item.type)){persist();panel=null;openPanel('inventory')}else notify('You are already restored.')});card.append(use)}b.append(card)});
}
function journalPanel(b){b.append(node('div','eyebrow','THE MAIN THREAD'),node('h2','',hero.campaign.title),node('p','',M.objective(hero)),node('p','muted',hero.campaign.witness));if(hero.campaign.flags.alliance)b.append(node('p','gold-label','Alliance: '+hero.campaign.flags.alliance));if(hero.campaign.stage==='complete')b.append(btn('Begin a new adventure',newAdventure,'primary'));b.append(node('h3','','Stories on the side'));for(const q of hero.world.quests){const card=node('div','quest-card');card.append(node('strong','',q.title),node('small','',q.state==='ready'?'Return to '+q.giver:q.state+' · '+q.progress+'/'+q.goal),node('p','',q.description));if(q.state==='offered')card.append(btn('Accept',()=>{M.acceptSide(hero,q.id);persist();panel=null;openPanel('journal')}));b.append(card)}if(!hero.world.quests.length)b.append(node('p','muted','Listen to the townsfolk. The world holds more than one story.'));b.append(node('h3','','The chronicle'));for(const event of hero.history.slice(0,50)){const p=node('div','journal-entry');p.append(node('small','','DAY '+event.day),node('p','',event.text));b.append(p)}if(hero.legacy.length){b.append(node('h3','','Legacies'));for(const c of hero.legacy)b.append(node('p','',c.title+' · '+c.ending+'\n'+c.text))}}
function mapPanel(b){b.append(node('h2','','The roads between'),node('p','muted','Three settlements, their old roads, and the places beneath them. Walking and travel advance the day.'));const map=node('div','world-map');hero.world.towns.forEach((town,i)=>{const card=node('div','map-town '+(hero.location.townId===i?'current':''));card.append(node('span','map-dot','⌖'),node('h3','',town.name),node('p','',town.description));const a=node('div','inline-actions');const travel=btn(hero.location.townId===i&&hero.location.type==='town'?'You are here':'Travel here',()=>travelTo(i),'primary');travel.disabled=hero.location.type==='dungeon'||hero.location.townId===i&&hero.location.type==='town';a.append(travel,btn('Old road',()=>{if(hero.location.type==='dungeon'){notify('Leave the undercrypt before traveling.');return}if(hero.location.townId!==i)travelTo(i,true);else changeLocation('wilds',i)}));card.append(a);map.append(card)});b.append(map);if(hero.location.type==='dungeon')b.append(node('p','warning-text','Find the stairs to return to the surface before traveling.'));b.append(node('h3','','Map legend'),node('p','muted','Gold: your main objective · Green: roads and stairs · Red: hostile creatures. The undercrypt map reveals as you explore.'))}
function travelMenu(){dialog({tag:'WHERE NEXT?',title:'The old road',text:'Beyond the gate lie ruined shrines, strangers, and the entrance to the undercrypt.',choices:[['Explore outside '+M.townOf(hero).name,()=>changeLocation('wilds')],['Consult the world map',()=>{dismiss();openPanel('map')}],['Stay in town',dismiss]]})}
function travelTo(id,road=false){
 if(hero.location.type==='dungeon'){notify('Find the undercrypt stairs first.');return}const town=hero.world.towns[id],key='journey-'+hero.location.townId+'-'+id+'-'+hero.world.day;const go=()=>{hero.world.hour+=2;changeLocation(road?'wilds':'town',id)};
 if(hero.world.events.includes(key)){go();return}hero.world.events.push(key);dialog({tag:'BETWEEN ONE PLACE AND ANOTHER',title:'A light beside the road',text:'On the road to '+town.name+', a traveler tends a small fire. A second shadow sits beside them, though the other seat is empty. “Will you tell us a true story?” they ask.',choices:[['Share a memory',()=>{const c=M.check(hero,'presence',11);if(c.success){M.gainXp(hero,18);hero.mp=Math.min(M.maxMp(hero),hero.mp+6);M.addLog(hero,'A stranger repaid your story with a moment of peace.')}else M.addLog(hero,'The stranger listened. Their second shadow did not.');go()},'Presence check · a chance to recover mana.'],['Study the second shadow',()=>{const c=M.check(hero,'lore',12);M.gainXp(hero,c.success?20:8);M.addLog(hero,c.success?'The second shadow belongs to a traveler who has not been born.':'You decide that not every mystery needs an answer today.');go()},'Lore check · discover an odd truth.'],['Keep walking',go,'Leave their secrets beside the road.']]});persist();
}
function directorConversation(e){
 if(!aiStatus.sharing){dialog({tag:'THE DUNGEON MASTER',title:'An open conversation',text:'Live AI conversation is available when the local edition is connected to your ChatGPT plan. You can also ask ChatGPT to write a story pack and import it here.',choices:[['Dungeon Master settings',()=>{dismiss();openPanel('director')}],['Return to '+e.name,()=>talk(e)]]});return}
 askDirector('I approach '+e.name+', the '+e.role+' at '+e.building+'. I say: ');
}
async function generateAdventure(first=false){
 const id=hero.id,campaignId=hero.campaign.id;const loading=dialog({tag:'THE WORLD IS TAKING SHAPE',title:'A story only this hero could find',text:'ChatGPT is weaving a new mystery from your character, history, and previous decisions. Your hero remains saved.',closable:false,choices:[]});loading.body.append(node('div','loading-rune','✧'));
 try{const pack=await AI.requestDirector(hero,'',{campaign:true,model:aiModel});if(hero?.id!==id||hero?.campaign.id!==campaignId)return;AI.applyAdventure(hero,pack);persist(true);dismiss();if(first)introduction();else notify('A new AI-written story is ready.','quest')}
 catch(e){if(hero?.id!==id||hero?.campaign.id!==campaignId)return;dialog({tag:'THE STORY CONNECTION PAUSED',title:'Your adventure is safe',text:e.message,choices:[['Try ChatGPT again',()=>generateAdventure(first)],['Use the procedural story',()=>{dismiss();if(first)introduction()}],['Connection settings',settings]]})}
}
function askDirector(initial=''){
 const d=dialog({tag:'YOUR OWN WORDS',title:'What do you do?',text:'Speak to someone, investigate an idea, or try an unexpected approach. The dungeon master knows your current location and history.',choices:[['Tell the dungeon master',()=>{const text=input.value.trim();if(text)runDirectorScene(text)}],['Cancel',dismiss]]});const input=node('textarea','director-input');input.maxLength=600;input.rows=4;input.value=initial;input.placeholder='I ask the innkeeper why no one will say the name of the old church…';d.body.insertBefore(input,d.list);input.focus();
}
async function runDirectorScene(action){
 const id=hero.id,world=hero.world.seed;const loading=dialog({tag:'THE DUNGEON MASTER IS LISTENING',title:'The world answers',text:'A new scene is being written around your choice.',closable:false,choices:[]});loading.body.append(node('div','loading-rune','✧'));
 try{const pack=await AI.requestDirector(hero,action,{model:aiModel});if(hero?.id!==id||hero?.world.seed!==world)return;M.addLog(hero,'You: '+action,'director');M.addLog(hero,pack.narration,'director');persist();showDirectorScene(pack)}catch(e){if(hero?.id!==id||hero?.world.seed!==world)return;dialog({tag:'CONNECTION INTERRUPTED',title:'Your choice has not been applied',text:e.message,choices:[['Try again',()=>runDirectorScene(action)],['Return to the world',dismiss],['Connection settings',settings]]})}
}
function showDirectorScene(pack){dialog({tag:'A NEW THREAD · AI DUNGEON MASTER',title:hero.campaign.title,text:pack.narration,choices:pack.choices.map(choice=>[choice.label,()=>{
 const c=choice.stat==='none'?{success:true}:M.check(hero,choice.stat,12+Math.floor(hero.level/5));let text;if(c.success){text=choice.result;switch(choice.reward){case'heal':hero.hp=Math.min(M.maxHp(hero),hero.hp+10);break;case'mana':hero.mp=Math.min(M.maxMp(hero),hero.mp+6);break;case'gold':M.gainGold(hero,8);break;case'reputation':hero.factions.town++;break;}M.gainXp(hero,choice.reward==='information'?8:5)}else{text='Your approach does not quite work. The world keeps its secret for now.';M.gainXp(hero,2)}M.addLog(hero,choice.label+': '+text,'director');persist();dialog({tag:c.success?'A CHOICE MADE':'THE DICE HAVE SPOKEN',title:choice.label,text:text+(c.roll?`\n\nD20 ${c.roll} + ${c.bonus} = ${c.total} / ${c.dc}`:''),choices:[['Continue in your own words',()=>askDirector()],['Return to the world',dismiss]]})},choice.stat==='none'?'No check':STAT_LABELS[choice.stat]+' check'])})}
function directorPanel(b){
 b.append(node('div','eyebrow','THE WORLD BEYOND THE SCRIPT'),node('h2','','Your dungeon master'),node('p','muted','A hero’s history should lead to unfamiliar stories. Keep playing procedural adventures, or connect ChatGPT to write entirely new mysteries and respond to your own words.'));
 const status=node('div','connection-status '+(aiStatus.sharing?'connected':''));status.append(node('strong','',aiStatus.sharing?'ChatGPT connected':aiStatus.available?'Local edition · not connected':'Browser edition'),node('p','',aiStatus.sharing?'Using your ChatGPT plan. Every request counts toward its limits.':aiStatus.available?'Sign in to authorize eligible ChatGPT plan usage.':'Live ChatGPT sign-in currently needs the local edition. Open start-sinfall.cmd on your Windows PC, or run npm start from the repository.'));b.append(status);
 if(aiStatus.sharing){b.append(btn('Take an action in your own words',()=>askDirector(),'primary'));if(hero.campaign.stage==='arrival')b.append(btn('Let ChatGPT write this adventure',()=>generateAdventure(true)));b.append(btn('Manage ChatGPT usage',()=>window.open('https://chatgpt.com/#settings/Usage','_blank','noopener')))}else if(aiStatus.available)b.append(btn('Continue with ChatGPT',signIn,'chatgpt-button'));
 b.append(node('h3','','Use this chat as your storyteller'),node('p','muted','Copy the story request into ChatGPT. Paste its JSON reply below to turn that original story into a playable adventure. This is a manual handoff; it does not enable live AI conversation.'));
 const copy=btn('Copy a campaign request',()=>{if(hero.campaign.stage!=='arrival'){notify('Begin a new adventure first, so your current story stays intact.');return}copyText(AI.campaignPrompt(hero))});b.append(copy);const text=node('textarea','story-import');text.rows=5;text.placeholder='Paste the JSON story pack from ChatGPT…';text.setAttribute('aria-label','Story pack JSON');b.append(text,btn('Import story pack',()=>{try{AI.applyAdventure(hero,AI.parseJson(text.value));persist(true);notify('Your new story is ready.','quest');panel=null;openPanel('journal')}catch(e){notify(e.message,'warning')}}));
 if(hero.campaign.stage==='complete')b.append(btn('Begin another adventure',newAdventure,'primary'));b.append(btn('Connection & display settings',settings,'text-button'));
}
async function signIn(){try{const r=await fetch('api/auth/start',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}),data=await r.json();if(!r.ok)throw Error(data.error||'Sign-in could not start.');window.location.assign(data.url)}catch(e){notify(e.message,'warning')}}
async function settings(){
 aiStatus=await AI.connection();const d=dialog({tag:'MAKE THE REALM YOURS',title:'Settings',text:'Your characters autosave separately. Export a hero or the whole collection to move between your phone and the local edition.',choices:[['How to play',howTo],['Export all heroes',()=>download('sinfall-collection.json',S.exportBook())],['Import saves',openImport],['Return',dismiss]],wide:true});
 const area=node('div','settings-grid');const qualityLabel=node('label','field-label','Graphics quality'),quality=node('select');for(const[v,l]of[['high','High · shadows and dense foliage'],['low','Performance · lighter on mobile']]){const o=node('option','',l);o.value=v;quality.append(o)}quality.value=prefs.quality||'high';quality.onchange=()=>{prefs.quality=quality.value;localStorage.setItem('sinfall-preferences',JSON.stringify(prefs));if(screen==='world'){dismiss();startGame()}else notify('Graphics preference saved.')};qualityLabel.append(quality);area.append(qualityLabel);
 const connected=node('section','settings-connection');connected.append(node('h3','','ChatGPT dungeon master'),node('p','',aiStatus.sharing?'Connected · using your ChatGPT plan.':aiStatus.available?'Local edition ready. Sign in to approve ChatGPT plan usage.':'The GitHub Pages edition runs without an AI account. Live ChatGPT plan sign-in is supported by the local edition included in this repo. Your phone can use manually imported ChatGPT story packs.'));
 if(aiStatus.sharing){connected.append(node('small','',aiStatus.account?.email||'ChatGPT account'));const modelLabel=node('label','field-label','Dungeon master model'),select=node('select');for(const m of aiStatus.models||[]){const o=node('option','',m.display_name||m.slug);o.value=m.slug;select.append(o)}aiModel=aiModel||aiStatus.models?.[0]?.slug||'';select.value=aiModel;select.onchange=()=>aiModel=select.value;modelLabel.append(select);connected.append(modelLabel,btn('Manage usage',()=>window.open('https://chatgpt.com/#settings/Usage','_blank','noopener')),btn('Disconnect locally',async()=>{await fetch('api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});aiStatus=await AI.connection();settings()}))}else if(aiStatus.available)connected.append(btn('Continue with ChatGPT',signIn,'chatgpt-button'));
 area.append(connected);d.body.insertBefore(area,d.list);if(S.storageError())d.body.insertBefore(btn('Recover the previous save collection',()=>{if(S.restoreRecovery()){notify('Recovered the previous collection.');dismiss();hero=null;menu()}else notify('No valid recovery copy was found.')}),d.list);
}
function howTo(){dialog({tag:'THE FIRST FEW STEPS',title:'Find your own story',text:'Walk through the village. Talk to the person marked with a gold diamond. Listen to rumors, take work from the notice board, visit the smith, and follow the road when you are ready.\n\nDesktop: WASD or arrow keys to walk. Drag the view to look. E interacts; Shift runs. V switches the dungeon camera. Escape closes a panel or opens the pause menu.\n\nPhone: use the left stick to walk, drag the world to look, and use the contextual Interact button on the right. The bottom bar opens your character, satchel, journal, map, and dungeon master.\n\nIn combat, read the enemy’s intention. Guard against heavy blows, interrupt dangerous attacks with class abilities, and equip better armor. Victory brings XP and talent points.\n\nEvery hero has their own save. A finished campaign leads to a new world with the same hero. Export saves to move them between devices.',choices:[['The road is waiting',dismiss]],wide:true})}
function openImport(){const input=$('file-import');input.value='';input.onchange=async()=>{if(!input.files[0])return;try{const heroes=S.importSave(await input.files[0].text());notify(`Imported ${heroes.length} hero${heroes.length>1?'es':''}.`);if(screen==='menu')menu();loadScreen()}catch(e){notify(e.message,'warning')}};input.click()}

document.addEventListener('keydown',e=>{
 if(e.key==='Escape'){if(modalRoot.children.length){if(!hero?.combat)dismiss()}else if(panel){panel=null;$('side-panel')?.replaceChildren()}else if(screen==='world')pauseMenu();return}
 if(e.key==='Tab'&&modalRoot.children.length){const focusables=[...modalRoot.querySelectorAll('button:not(:disabled),a,input,textarea,select')];if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
 if(screen!=='world'||modalRoot.children.length||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;
 const keys={i:'inventory',j:'journal',m:'map',c:'character'};if(keys[e.key.toLowerCase()]){e.preventDefault();openPanel(keys[e.key.toLowerCase()])}
});
window.addEventListener('pagehide',()=>{if(hero)S.saveHero(hero)});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&hero){S.saveHero(hero);realm?.keys.clear()}});
try{const migrated=S.migrateOldSave();if(migrated)notify('Your previous hero has been brought into the rebuilt realm.')}catch{}
menu();AI.connection().then(s=>{aiStatus=s;aiModel=s.models?.[0]?.slug||'';if(new URLSearchParams(location.search).has('connected'))notify(s.sharing?'ChatGPT connected. Your dungeon master is ready.':s.error||'ChatGPT sign-in did not enable plan usage.',s.sharing?'':'warning')});
